// Task CRUD and status transitions.
// Validates users exist, enforces status machine, integrates cache/audit.

import { findById, validateExists } from './users.js';
import { record } from './audit.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

// Valid status transitions: open -> in_progress -> done
const VALID_TRANSITIONS: Record<Task['status'], Task['status'][]> = {
  open: ['in_progress'],
  in_progress: ['done'],
  done: [],
};

class TaskManager {
  private tasks = new Map<string, Task>();
  private cache = new Cache();

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    // Validate both users exist
    validateExists(input.createdBy);
    validateExists(input.assignee);
    // Validate title is non-empty
    if (!input.title.trim()) {
      throw new Error('Title must not be empty');
    }

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };
    this.tasks.set(task.id, task);
    this.cache.set(task.id, task, 60000);
    record({ action: 'create', userId: input.createdBy, taskId: task.id, timestamp: Date.now() });
    return task;
  }

  getTask(id: string): Task | null {
    const cached = this.cache.get<Task>(id);
    if (cached) return cached;
    const task = this.tasks.get(id) ?? null;
    if (task) {
      this.cache.set(id, task, 60000);
    }
    return task;
  }

  updateStatus(id: string, status: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const allowed = VALID_TRANSITIONS[task.status];
    if (!allowed.includes(status)) {
      throw new Error(
        `Invalid status transition: ${task.status} -> ${status}`
      );
    }

    task.status = status;
    this.cache.invalidate(id);
    record({
      action: 'status_change',
      userId: task.createdBy,
      taskId: task.id,
      details: `changed to ${status}`,
      timestamp: Date.now(),
    });
    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) return false;
    const { canDelete } = await import('./permissions.js');
    if (!canDelete(task, userId)) return false;

    this.tasks.delete(id);
    this.cache.invalidate(id);
    record({ action: 'delete', userId, taskId: id, timestamp: Date.now() });
    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId,
    );
  }

  clear() {
    this.tasks.clear();
    // also clear cache entries
    // (Map.clear is fine but we also want to drop cache refs)
    this.cache = new Cache();
  }
}

export const taskManager = new TaskManager();

