{"content": "// Permission checks.

import { findById } from './users.js';

export function canDelete(task: { createdBy: string }, userId: string): boolean {
  const user = findById(userId);
  if (!user) return false;
  // Admin can delete any task; owner can delete their own
  return user.role === 'admin' || task.createdBy === userId;
}

export function canExport(userId: string): boolean {
  const user = findById(userId);
  if (!user) return false;
  return user.role === 'admin';
}
