import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

function csvEscape(value: string): string {
  if (
    value.includes(',') ||
    value.includes('"') ||
    value.includes('\n') ||
    value.includes('\r')
  ) {
    return '"' + value.replace(/"/g, '""') + '"';
  }
  return value;
}

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error(`User ${userId} does not have export permission`);
  }

  const tasks = Array.from((taskManager as unknown as { tasks: Map<string, unknown> }).tasks
    ? (taskManager as unknown as { tasks: Map<string, { id: string; title: string; status: string; assignee: string; createdAt: number }> }).tasks.values()
    : []);

  // Access private tasks map via bracket cast
  const allTasks = (taskManager as unknown as { [key: string]: unknown }).tasks as Map<
    string,
    { id: string; title: string; status: string; assignee: string; createdAt: number }
  >;
  const rows = Array.from(allTasks.values());

  const header = 'id,title,status,assignee,createdAt';
  const lines = rows.map(
    (t) =>
      `${csvEscape(t.id)},${csvEscape(t.title)},${csvEscape(t.status)},${csvEscape(t.assignee)},${t.createdAt}`
  );

  record({ action: 'export', userId, timestamp: Date.now() });

  return [header, ...lines].join('\n');
}

